package school.magiccodex.client;
import net.fabricmc.fabric.api.client.networking.v1.*;import net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry;import net.minecraft.client.MinecraftClient;import net.minecraft.network.RegistryByteBuf;import net.minecraft.network.codec.PacketCodec;import net.minecraft.network.packet.CustomPayload;import net.minecraft.util.Identifier;import school.magiccodex.protocol.HousingSearchProtocol;import school.magiccodex.protocol.HousingSearchProtocol.*;import java.util.*;
/** Connection-owned, generation-checked UI state; no database or search work on render thread. */
final class HousingSearchClient{
 record Payload(byte[] bytes)implements CustomPayload{static final Id<Payload>ID=new Id<>(Identifier.of(HousingSearchProtocol.CHANNEL));static final PacketCodec<RegistryByteBuf,Payload>CODEC=new PacketCodec<>(){public Payload decode(RegistryByteBuf b){int n=b.readableBytes();if(n>HousingSearchProtocol.MAX_BYTES){b.skipBytes(n);return new Payload(new byte[0]);}var bytes=new byte[n];b.readBytes(bytes);return new Payload(bytes);}public void encode(RegistryByteBuf b,Payload p){b.writeBytes(p.bytes());}};public Id<Payload>getId(){return ID;}}
 static final HousingSearchGeneration gate=new HousingSearchGeneration();static long expected,started;static int wantedPage;static Page page;static boolean loading;
 static void initialize(){PayloadTypeRegistry.playS2C().register(Payload.ID,Payload.CODEC);PayloadTypeRegistry.playC2S().register(Payload.ID,Payload.CODEC);ClientPlayNetworking.registerGlobalReceiver(Payload.ID,(payload,context)->{var player=context.player();try{var result=HousingSearchProtocol.page(payload.bytes());context.client().execute(()->{if(context.client().player!=player||!gate.accepts(result.generation())||!(context.client().currentScreen instanceof HousingScreen screen)||!screen.searchVisible())return;page=result;loading=false;});}catch(IllegalArgumentException ignored){}});ClientPlayConnectionEvents.JOIN.register((h,s,c)->invalidate());ClientPlayConnectionEvents.DISCONNECT.register((h,c)->invalidate());}
 static void invalidate(){expected=gate.next();page=null;loading=false;}
 static void send(String text,int number){expected=gate.next();wantedPage=number;started=net.minecraft.util.Util.getMeasuringTimeMs();page=null;loading=true;if(MinecraftClient.getInstance().getNetworkHandler()==null||!ClientPlayNetworking.canSend(Payload.ID)){page=new Page(expected,number,false,List.of(),"유저 검색 서버 업데이트가 필요합니다.");loading=false;return;}ClientPlayNetworking.send(new Payload(HousingSearchProtocol.encode(new Query(expected,number,text))));}
 static void tick(){if(loading&&net.minecraft.util.Util.getMeasuringTimeMs()-started>6000){expected=gate.next();loading=false;page=new Page(expected,wantedPage,false,List.of(),"검색 응답이 늦습니다. Enter로 다시 검색해 주세요.");}}
 private HousingSearchClient(){}
}
